/* Môn Đọc thương mại — 国际商务汉语（上册）. 10 tập, mỗi tập: 3 màn hội thoại (核心课文), 语言要点, 3 bài 阅读理解, 商务背景 và 生活短剧.
   Nguyên văn theo giáo trình (bản quét có lỗi nhận dạng chữ, đã đối chiếu ảnh trang và sửa; một số bài đọc dài được rút gọn, có ghi ở dòng nguồn). Chỉ dùng tiếng Trung và tiếng Việt.
   Bài giảng tiếng Việt, nghĩa từ, bài tập tự kiểm tra và đáp án tham khảo do Claude soạn. Văn bản pháp luật và thông lệ thương mại trong sách là bản cũ (1985, 1990), chỉ để học từ ngữ. */
