    { t: 'open', q: '思考：中国代表的做法对商务促销有什么启发？', items: [['用3–4句话回答。', 'Gợi ý: 商战贵在出奇制胜；让产品自己说话，让顾客亲身体验产品的好处，比空口宣传更有说服力；遇到不公平待遇要冷静，寻找机会。']] }
